import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import StudentDashboard from './components/StudentDashboard';
import TeacherDashboard from './components/TeacherDashboard';
import Footer from './components/Footer';
import Login from './components/Login';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState(null); 
  const [userName, setUserName] = useState('User');

  const handleLoginSubmit = async (username, password) => {
    try {
      const response = await fetch('http://localhost:8081/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setUserRole(data.role); 
        setUserName(data.name);
        setCurrentPage('Dashboard');
      } else { alert('Invalid Username or Password!'); }
    } catch (error) { alert('Server error!'); }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserRole(null);
    setCurrentPage('Home');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      <Navbar onLoginClick={() => setShowLoginModal(true)} isLoggedIn={isLoggedIn} userName={userName} setCurrentPage={setCurrentPage} currentPage={currentPage} />

      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
        {currentPage === 'Teachers' && <Teachers />}
        {currentPage === 'About' && <About />}
        
        {currentPage === 'Dashboard' && isLoggedIn && (
          <div style={{ flex: 1, display: 'flex' }}>
            {userRole === 'admin' && <LmsDashboard userName={userName} handleLogout={handleLogout} />}
            {userRole === 'teacher' && <TeacherDashboard teacherData={{name: userName}} />}
            {userRole === 'student' && <StudentDashboard studentData={{name: userName}} />}
          </div>
        )}
      </main>

      <Footer /> 

      {showLoginModal && <Login setShowLoginModal={setShowLoginModal} handleLoginSubmit={handleLoginSubmit} />}
    </div>
  );
}
